import { api } from './authService';

const userService = {
  /** GET /users */
  getAll: async (params = {}) => {
    const { data } = await api.get('/users', { params });
    return data?.data ?? data;
  },

  /** GET /users/{id} */
  getById: async (id) => {
    const { data } = await api.get(`/users/${id}`);
    return data?.data ?? data;
  },

  /** POST /users — création via /auth/register (ADMIN) */
  create: async (payload) => {
    const { data } = await api.post('/auth/register', payload);
    return data?.data ?? data;
  },

  /** PUT /users/{id} */
  update: async (id, payload) => {
    const { data } = await api.put(`/users/${id}`, payload);
    return data?.data ?? data;
  },

  /**
   * PATCH /users/{id}/role
   * Body: { role } — valeurs backend attendues : ADMIN | RECEPTIONNISTE | CLIENT
   */
  updateRole: async (id, role) => {
    // Normalise le rôle frontend vers backend
    const backendRole = {
      admin: 'ADMIN',
      receptionist: 'RECEPTIONNISTE',
      client: 'CLIENT',
    }[role] ?? role.toUpperCase();

    const { data } = await api.patch(`/users/${id}/role`, { role: backendRole });
    return data?.data ?? data;
  },

  /** DELETE /users/{id} */
  delete: async (id) => {
    const { data } = await api.delete(`/users/${id}`);
    return data?.data ?? data;
  },

  /** PATCH /users/{id}/activate */
  activate: async (id) => {
    const { data } = await api.patch(`/users/${id}/activate`);
    return data?.data ?? data;
  },

  /** PATCH /users/{id}/deactivate */
  deactivate: async (id) => {
    const { data } = await api.patch(`/users/${id}/deactivate`);
    return data?.data ?? data;
  },
};

export default userService;
